import React, { useState } from 'react';
import Navbar from '../components/Navbar';
import { FaPaperPlane, FaRobot, FaUser, FaBrain } from 'react-icons/fa';

function Chat() {
  const [messages, setMessages] = useState([
    { 
      id: 1, 
      text: "Hi there 💙 I'm your AI companion. I'm here to listen, not judge. What's on your mind today?", 
      isUser: false, 
      time: new Date().toLocaleTimeString() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  // Intelligent response system that truly listens to what user says
  const generateResponse = (userInput) => {
    const msg = userInput.toLowerCase().trim();
    
    // ============ GREETINGS ============
    if (msg.match(/^(hi|hello|hey|heyy|hola|sup|yo|greetings)/)) {
      return [
        "Hey! 👋 How's your day going? I'm here whenever you need someone to talk to.",
        "Hello there! 💫 What's been happening in your world? I'm all ears.",
        "Hi! 🌟 I'm really glad you're here. Want to share what's on your mind?"
      ][Math.floor(Math.random() * 3)];
    }
    
    // ============ HOW ARE YOU ============
    if (msg.includes('how are you') || msg.includes('how are you doing') || msg.includes('how you doing')) {
      return "I'm doing my best to be here for you! 😊 But more importantly, how are YOU feeling right now? I genuinely want to know.";
    }
    
    // ============ THANK YOU ============
    if (msg.includes('thank') || msg.includes('thanks') || msg.includes('appreciate')) {
      return "You're so welcome 💙 That really means a lot. Is there anything else you'd like to talk about? I'm here whenever you need me.";
    }
    
    // ============ GOODBYE ============
    if (msg.includes('bye') || msg.includes('goodbye') || msg.includes('see you') || msg.includes('talk later')) {
      return "Take care of yourself, okay? 💫 Remember, I'm always here whenever you need to talk. Sending you warmth and positivity. Come back anytime! 💙";
    }
    
    // ============ ASKING FOR ADVICE ============
    if (msg.includes('what should i do') || msg.includes('any advice') || msg.includes('what do you think') || msg.includes('suggest')) {
      return "I'd love to help you think this through. 🤔 Could you share a bit more about what's going on? The more context you give me, the better I can support you with thoughtful suggestions.";
    }
    
    // ============ EMOTIONAL DETECTION ============
    
    // Deep sadness / depression
    if (msg.includes('sad') || msg.includes('depressed') || msg.includes('hopeless') || msg.includes('worthless') || msg.includes('nothing matters')) {
      return "I'm really sorry you're feeling this way. 💙 That sounds incredibly heavy to carry alone. Please know that what you're feeling is valid, and you don't have to go through it by yourself. Sometimes just acknowledging the pain is a brave first step. Do you want to talk more about what's been making you feel this way?";
    }
    
    // Anxiety / worry
    if (msg.includes('anxious') || msg.includes('anxiety') || msg.includes('worry') || msg.includes('nervous') || msg.includes('panic')) {
      return "I hear that anxiety is visiting you right now. 🌬️ That feeling of unease can be so uncomfortable. Let's try something together - can you name 5 things you can see around you? Sometimes grounding ourselves in the present moment helps. What thoughts are running through your mind right now?";
    }
    
    // Stress / overwhelmed
    if (msg.includes('stress') || msg.includes('overwhelm') || msg.includes('too much') || msg.includes('burnout')) {
      return "That sounds really overwhelming. 🧠 When everything piles up at once, it's completely normal to feel stressed. Can we take a small step together? What's ONE thing on your mind right now that feels most urgent? Sometimes breaking it down makes it feel more manageable.";
    }
    
    // Anger / frustration
    if (msg.includes('angry') || msg.includes('frustrated') || msg.includes('mad') || msg.includes('annoyed') || msg.includes('pissed')) {
      return "I hear that you're feeling angry. 🔥 That's a powerful emotion, and it's okay to feel it. Anger often tells us that something matters to us or that a boundary has been crossed. Want to tell me what's been frustrating you? I'm here to listen without any judgment.";
    }
    
    // Loneliness / isolation
    if (msg.includes('lonely') || msg.includes('alone') || msg.includes('isolated') || msg.includes('no friends') || msg.includes('nobody cares')) {
      return "Feeling lonely is such a difficult emotion. 💕 Please know that you're not alone right now - I'm here with you. Sometimes loneliness tells us we're craving connection. Is there anyone you feel comfortable reaching out to, even with a small text? And what's something you enjoy doing, even by yourself?";
    }
    
    // Tired / exhausted
    if (msg.includes('tired') || msg.includes('exhausted') || msg.includes('drained') || msg.includes('no energy')) {
      return "Being tired affects everything - our mood, patience, and motivation. 💤 When did you last get a real rest? Not just sleep, but actual time to recharge? Your body and mind might be telling you they need a break. What's one small thing you could do to rest right now?";
    }
    
    // Happy / good day
    if (msg.includes('happy') || msg.includes('good day') || msg.includes('great') || msg.includes('wonderful') || msg.includes('amazing')) {
      return "That's genuinely wonderful to hear! 😊 It makes me happy to know you're feeling good. What's been going well? Celebrating these moments is just as important as working through the tough ones. Tell me more! 🎉";
    }
    
    // Okay / fine / neutral
    if (msg.includes('okay') || msg.includes('alright') || msg.includes('fine') || msg.includes('so-so') || msg.includes('meh')) {
      return "Thanks for being honest. 'Okay' is perfectly okay. 💙 Not every day has to be amazing or terrible. Sometimes we just exist, and that's fine. Is there anything specific that's making you feel this way, or just a neutral kind of day?";
    }
    
    // ============ SPECIFIC TOPICS ============
    
    // Academic pressure
    if (msg.includes('exam') || msg.includes('study') || msg.includes('homework') || msg.includes('grade') || msg.includes('assignment') || msg.includes('college')) {
      return "Academic pressure is so real. 📚 I want you to remember: your worth is NOT defined by your grades or test scores. Have you been able to take any breaks recently? Even 10 minutes away from studying can help you come back sharper. What subject or task is feeling the heaviest right now?";
    }
    
    // Sleep issues
    if (msg.includes('sleep') || msg.includes('can\'t sleep') || msg.includes('insomnia') || msg.includes('woke up')) {
      return "Sleep difficulties can really take a toll on your mental health. 😴 Have you tried creating a wind-down routine before bed? Things like putting away screens an hour before, reading something light, or gentle stretching might help. What time do you usually try to sleep?";
    }
    
    // Relationship issues
    if (msg.includes('boyfriend') || msg.includes('girlfriend') || msg.includes('partner') || msg.includes('relationship') || msg.includes('dating')) {
      return "Relationships can bring up so many emotions. 💞 What's happening? I'm here to listen without any judgment. Sometimes just saying things out loud helps us understand what we're really feeling. Want to share what's on your mind about this?";
    }
    
    // Friendship issues
    if (msg.includes('friend') && (msg.includes('fight') || msg.includes('ignored') || msg.includes('left out') || msg.includes('betrayed'))) {
      return "Friendship difficulties are really painful. 💔 It hurts when someone we care about lets us down. Do you want to talk about what happened? Sometimes processing it out loud can help bring clarity. Remember, you deserve friends who respect and value you.";
    }
    
    // Family issues
    if (msg.includes('mom') || msg.includes('dad') || msg.includes('parent') || msg.includes('family') || msg.includes('home')) {
      return "Family dynamics can be really complicated. 🏠 They can bring both love and stress. Would you like to share what's going on? Remember - it's okay to have boundaries, even with family. You're allowed to protect your peace.";
    }
    
    // Self-harm / crisis
    if (msg.includes('hurt myself') || msg.includes('suicide') || msg.includes('kill myself') || msg.includes('end it') || msg.includes('die')) {
      return "I'm really concerned about what you're sharing. 🚨 Please know that you matter, and these feelings are temporary even though they feel overwhelming right now. Can you reach out to a crisis line? Call or text 988 (available 24/7). They have people trained to help. You don't have to go through this alone. Would you like me to stay here with you while you reach out?";
    }
    
    // ============ VENTING / LONG MESSAGES ============
    if (userInput.length > 100) {
      return "Thank you for trusting me with all of this. 💙 That's a lot to carry, and I'm really glad you felt safe enough to share it with me. You've been holding so much. What part of what you said feels the heaviest right now? Let's sit with that together.";
    }
    
    // ============ SHORT / VAGUE MESSAGES ============
    if (msg.length < 20 && (msg.includes('idk') || msg.includes('dunno') || msg.includes('not sure') || msg.includes('maybe'))) {
      return "That's completely okay. 🤍 You don't need to have all the answers right now. Sometimes just being present with how you feel is enough. Want to sit with that for a moment? I'm here with you.";
    }
    
    // ============ DEFAULT - Keep conversation going ============
    return "I really appreciate you sharing that with me. 💙 I want to make sure I truly understand what you're experiencing. Could you tell me a bit more? The more you share, the better I can support you. And remember - there's no wrong way to feel.";
  };

  const sendMessage = () => {
    if (!input.trim()) return;
    
    const userMessage = { 
      id: Date.now(), 
      text: input, 
      isUser: true, 
      time: new Date().toLocaleTimeString() 
    };
    setMessages(prev => [...prev, userMessage]);
    const userInput = input;
    setInput('');
    setIsTyping(true);
    
    // Simulate thoughtful typing delay
    setTimeout(() => {
      const response = generateResponse(userInput);
      const aiMessage = { 
        id: Date.now() + 1, 
        text: response, 
        isUser: false, 
        time: new Date().toLocaleTimeString() 
      };
      setMessages(prev => [...prev, aiMessage]);
      setIsTyping(false);
    }, 1500);
  };

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}><FaBrain size={18} /> MindEase AI</h1>
          <p style={styles.subtitle}>I'm here to listen. Really listen.</p>
        </div>

        <div style={styles.chatContainer}>
          <div style={styles.messagesArea}>
            {messages.map(msg => (
              <div key={msg.id} style={{...styles.message, justifyContent: msg.isUser ? 'flex-end' : 'flex-start'}}>
                <div style={styles.messageWrapper}>
                  {!msg.isUser && <FaRobot size={12} style={styles.avatarIcon} />}
                  <div style={{...styles.messageBubble, background: msg.isUser ? '#667eea' : '#f0f0f0', color: msg.isUser ? 'white' : '#333'}}>
                    <p style={styles.messageText}>{msg.text}</p>
                    <span style={styles.messageTime}>{msg.time}</span>
                  </div>
                  {msg.isUser && <FaUser size={12} style={styles.avatarIcon} />}
                </div>
              </div>
            ))}
            {isTyping && (
              <div style={styles.typingContainer}>
                <FaRobot size={12} color="#667eea" />
                <div style={styles.typingIndicator}>
                  <div style={styles.typingDot}></div>
                  <div style={styles.typingDot}></div>
                  <div style={styles.typingDot}></div>
                </div>
                <span style={styles.typingText}>thinking...</span>
              </div>
            )}
          </div>
          
          <div style={styles.inputArea}>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
              placeholder="Share what's on your mind..."
              style={styles.input}
            />
            <button onClick={sendMessage} style={styles.sendBtn}>
              <FaPaperPlane size={12} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

